CREATE TABLE IF NOT EXISTS corporate_entities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), legal_name text NOT NULL, short_name text, entity_type text NOT NULL, jurisdiction text NOT NULL, registration_number text, parent_entity_id uuid REFERENCES corporate_entities(id) ON DELETE SET NULL, ownership_model text, ownership_percentage numeric(7,4), purpose text, status text NOT NULL DEFAULT 'Planned', incorporation_date date, local_director_required boolean NOT NULL DEFAULT false, regulatory_status text, protected_interest boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS entity_relationships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_entity_id uuid NOT NULL REFERENCES corporate_entities(id) ON DELETE CASCADE, to_entity_id uuid NOT NULL REFERENCES corporate_entities(id) ON DELETE CASCADE, relationship_type text NOT NULL, ownership_percentage numeric(7,4), effective_date date, status text NOT NULL DEFAULT 'Planned', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS entity_jurisdiction_requirements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid NOT NULL REFERENCES corporate_entities(id) ON DELETE CASCADE, jurisdiction text NOT NULL, requirement_type text NOT NULL, requirement_name text NOT NULL, status text NOT NULL DEFAULT 'Pending', due_date date, responsible_officer text, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS entity_reserved_matters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid NOT NULL REFERENCES corporate_entities(id) ON DELETE CASCADE, matter text NOT NULL, approval_level text NOT NULL, protected boolean NOT NULL DEFAULT false, notes text, created_at timestamptz NOT NULL DEFAULT now());
