INSERT INTO corporate_entities(legal_name,short_name,entity_type,jurisdiction,ownership_model,purpose,status) SELECT 'OSANVAULT AFRICA LTD','ÒsánVault Africa','Parent Company','Nigeria','Parent / controlling entity','Continental holding, governance, strategy and institutional stewardship.','Active' WHERE NOT EXISTS (SELECT 1 FROM corporate_entities WHERE legal_name='OSANVAULT AFRICA LTD');
INSERT INTO corporate_entities(legal_name,short_name,entity_type,jurisdiction,parent_entity_id,ownership_model,purpose,status) SELECT 'ÒsánVault Africa Regional Holdings — West Africa','OV West Africa','Regional Holding','West Africa',(SELECT id FROM corporate_entities WHERE legal_name='OSANVAULT AFRICA LTD'),'Wholly controlled where legally permitted','Regional coordination and investment platform for West African operations.','Planned' WHERE NOT EXISTS (SELECT 1 FROM corporate_entities WHERE legal_name='ÒsánVault Africa Regional Holdings — West Africa');
INSERT INTO corporate_entities(legal_name,short_name,entity_type,jurisdiction,parent_entity_id,ownership_model,purpose,status) SELECT 'ÒsánVault Africa Land & Asset SPV Framework','OV Asset SPVs','SPV Platform','Multi-jurisdiction Africa',(SELECT id FROM corporate_entities WHERE legal_name='OSANVAULT AFRICA LTD'),'Controlled / project-specific','Ring-fence land, property, infrastructure and other strategic assets at project level.','Planned' WHERE NOT EXISTS (SELECT 1 FROM corporate_entities WHERE legal_name='ÒsánVault Africa Land & Asset SPV Framework');
INSERT INTO entity_relationships(from_entity_id,to_entity_id,relationship_type,status,notes) SELECT p.id,r.id,'Regional parent / strategic control','Planned','Illustrative future structure; activate only after legal, tax and regulatory review.' FROM corporate_entities p,corporate_entities r WHERE p.legal_name='OSANVAULT AFRICA LTD' AND r.legal_name='ÒsánVault Africa Regional Holdings — West Africa' AND NOT EXISTS (SELECT 1 FROM entity_relationships e WHERE e.from_entity_id=p.id AND e.to_entity_id=r.id);
INSERT INTO entity_relationships(from_entity_id,to_entity_id,relationship_type,status,notes) SELECT p.id,s.id,'SPV platform sponsor / governance control','Planned','Project entities should be ring-fenced and independently documented.' FROM corporate_entities p,corporate_entities s WHERE p.legal_name='OSANVAULT AFRICA LTD' AND s.legal_name='ÒsánVault Africa Land & Asset SPV Framework' AND NOT EXISTS (SELECT 1 FROM entity_relationships e WHERE e.from_entity_id=p.id AND e.to_entity_id=s.id);
INSERT INTO entity_reserved_matters(entity_id,matter,approval_level,protected,notes) SELECT id,'Transfer or encumbrance of strategic indigenous/community-sensitive assets','Board + applicable shareholder + stewardship review',true,'No transaction should bypass applicable local law, customary rights processes or project-level protections.' FROM corporate_entities WHERE legal_name='OSANVAULT AFRICA LTD' AND NOT EXISTS (SELECT 1 FROM entity_reserved_matters WHERE matter='Transfer or encumbrance of strategic indigenous/community-sensitive assets');
INSERT INTO entity_reserved_matters(entity_id,matter,approval_level,protected,notes) SELECT id,'Formation of a new country subsidiary or material SPV','Board + local legal/regulatory review',false,'Country entry requires local corporate, tax, ownership and licensing analysis.' FROM corporate_entities WHERE legal_name='OSANVAULT AFRICA LTD' AND NOT EXISTS (SELECT 1 FROM entity_reserved_matters WHERE matter='Formation of a new country subsidiary or material SPV');